import{_ as p,a0 as l,w as o,s as h,I as n,x as a,a1 as e,A as t,ao as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"這些技巧讓 Bash 命令歷史更加有用 | LCTT x X-CMD","titleTemplate":false,"description":"這些技巧讓 Bash 命令歷史更加有用 | LCTT (202007) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"這些技巧讓 Bash 命令歷史更加有用 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"這些技巧讓 Bash 命令歷史更加有用 | LCTT (202007) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202007/20200625 Make Bash history more useful with these tips","title":"這些技巧讓 Bash 命令歷史更加有用","tag":"202007","desc":""},"relativePath":"202007/20200625 Make Bash history more useful with these tips.md","filePath":"[post].md"}'),d={name:"202007/20200625 Make Bash history more useful with these tips.md"};function u(c,s,g,k,b,f){const i=l("Link");return o(),h("div",null,[s[20]||(s[20]=n("h1",{id:"這些技巧讓-bash-命令歷史更加有用",tabindex:"-1"},[a("這些技巧讓 Bash 命令歷史更加有用 "),n("a",{class:"header-anchor",href:"#這些技巧讓-bash-命令歷史更加有用","aria-label":"Permalink to “這些技巧讓 Bash 命令歷史更加有用”"},"​")],-1)),s[21]||(s[21]=n("blockquote",null,[n("p",null,"告訴 Bash 你想要它記住什麼，甚至刪除不需要的記錄重寫歷史。")],-1)),s[22]||(s[22]=n("p",null,[n("img",{src:"https://img.linux.net.cn/data/attachment/album/202007/05/091205hkg0egl2gge2gx9z.jpg",alt:""})],-1)),n("p",null,[s[1]||(s[1]=a("運行 ",-1)),e(i,{href:"https://opensource.com/resources/what-bash"},{default:t(()=>[...s[0]||(s[0]=[a("Bash",-1)])]),_:1}),s[2]||(s[2]=a(" 的 Linux 終端有內置的歷史記錄，你可以用來跟蹤最近的操作。要查看你的 Bash 會話的歷史記錄，請使用內置命令 ",-1)),s[3]||(s[3]=n("code",null,"history",-1)),s[4]||(s[4]=a("：",-1))]),s[23]||(s[23]=r(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo &quot;foo&quot;</span></span>
<span class="line"><span>foo</span></span>
<span class="line"><span>$ echo &quot;bar&quot;</span></span>
<span class="line"><span>bar</span></span>
<span class="line"><span>$ history</span></span>
<span class="line"><span>  1  echo &quot;foo&quot;</span></span>
<span class="line"><span>  2  echo &quot;bar&quot;</span></span>
<span class="line"><span>  3  history</span></span></code></pre></div><p>與大多數命令不一樣，<code>history</code> 命令不是文件系統上的可執行文件，而是 Bash 的功能。你可以使用 <code>type</code> 命令來驗證：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ type history</span></span>
<span class="line"><span>history is a shell builtin</span></span></code></pre></div><h3 id="歷史控制" tabindex="-1">歷史控制 <a class="header-anchor" href="#歷史控制" aria-label="Permalink to “歷史控制”">​</a></h3><p>shell 歷史記錄的行數上限由 <code>HISTSIZE</code> 變量定義。你可以在 <code>.bashrc</code> 文件中設置此變量。以下將你的歷史記錄設置為 3,000 行，之後將最早的行刪除以為最新命令騰出空間，該命令位於列表的底部：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>export HISTSIZE=3000</span></span></code></pre></div><p>還有其他與歷史相關的變量。 <code>HISTCONTROL</code> 變量控制哪些歷史被記錄。你可以在 <code>.bashrc</code> 中寫入下面的行來強制 Bash 排除以空格開頭的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>export HISTCONTROL=$HISTCONTROL:ignorespace</span></span></code></pre></div><p>現在，如果你輸入以空格開頭的命令，那麼它將不會記錄在歷史記錄中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo &quot;hello&quot;</span></span>
<span class="line"><span>$     mysql -u bogus -h badpassword123 mydatabase</span></span>
<span class="line"><span>$ echo &quot;world&quot;</span></span>
<span class="line"><span>$ history</span></span>
<span class="line"><span>  1  echo &quot;hello&quot;</span></span>
<span class="line"><span>  2  echo &quot;world&quot;</span></span>
<span class="line"><span>  3  history</span></span></code></pre></div><p>你也可以避免重複的條目：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>export HISTCONTROL=$HISTCONTROL:ignoredups</span></span></code></pre></div><p>現在，如果你一個接着一個輸入兩個命令，歷史記錄中只會顯示一個：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls</span></span>
<span class="line"><span>$ ls</span></span>
<span class="line"><span>$ ls</span></span>
<span class="line"><span>$ history</span></span>
<span class="line"><span>  1  ls</span></span>
<span class="line"><span>  2  history</span></span></code></pre></div><p>如果你喜歡這兩個忽略功能，那麼可以使用 <code>ignoreboth</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>export HISTCONTROL=$HISTCONTROL:ignoreboth</span></span></code></pre></div><h3 id="從歷史記錄中刪除命令" tabindex="-1">從歷史記錄中刪除命令 <a class="header-anchor" href="#從歷史記錄中刪除命令" aria-label="Permalink to “從歷史記錄中刪除命令”">​</a></h3><p>有時你會犯一個錯誤，在 shell 中輸入了一些敏感內容，或者你​​只是想清理歷史記錄，以便它更準確地表示讓某件事正常工作所採取的步驟。如果要從 Bash 的歷史記錄中刪除命令，請在要刪除的項目的行號上使用 <code>-d</code> 選項：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo &quot;foo&quot;</span></span>
<span class="line"><span>foo</span></span>
<span class="line"><span>$ echo &quot;bar&quot;</span></span>
<span class="line"><span>bar</span></span>
<span class="line"><span>$ history | tail</span></span>
<span class="line"><span>  535  echo &quot;foo&quot;</span></span>
<span class="line"><span>  536  echo &quot;bar&quot;</span></span>
<span class="line"><span>  537  history | tail</span></span>
<span class="line"><span>$ history -d 536</span></span>
<span class="line"><span>$ history | tail</span></span>
<span class="line"><span>  535  echo &quot;foo&quot;</span></span>
<span class="line"><span>  536  history | tail</span></span>
<span class="line"><span>  537  history -d 536</span></span>
<span class="line"><span>  538  history | tail</span></span></code></pre></div><p>要停止添加 <code>history</code> 條目，只要在 <code>HISTCONTROL</code> 環境變量中有 <code>ignorespace</code>，就可以在命令前添加空格：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$  history | tail</span></span>
<span class="line"><span>  535  echo &quot;foo&quot;</span></span>
<span class="line"><span>  536  echo &quot;bar&quot;</span></span>
<span class="line"><span>$  history -d 536</span></span>
<span class="line"><span>$  history | tail</span></span>
<span class="line"><span>  535  echo &quot;foo&quot;</span></span></code></pre></div><p>你可以使用 <code>-c</code> 選項清除所有會話歷史記錄：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ history -c</span></span>
<span class="line"><span>$  history</span></span>
<span class="line"><span>$</span></span></code></pre></div><h3 id="history-命令的經驗" tabindex="-1">history 命令的經驗 <a class="header-anchor" href="#history-命令的經驗" aria-label="Permalink to “history 命令的經驗”">​</a></h3><p>操縱歷史通常沒有聽起來那麼危險，尤其是當你有目標地管理它時。例如，如果你要記錄一個複雜的問題，通常最好使用會話歷史來記錄命令，因為通過將命令插入歷史記錄，你能運行它們並從而測試過程。很多時候，不執行歷史命令會導致忽略小的步驟或寫錯小細節。</p><p>按需使用歷史會話，並明智地控制歷史記錄。享受歷史修改吧！</p><hr>`,27)),n("p",null,[s[6]||(s[6]=a("via: ",-1)),e(i,{href:"https://opensource.com/article/20/6/bash-history-control"},{default:t(()=>[...s[5]||(s[5]=[a("https://opensource.com/article/20/6/bash-history-control",-1)])]),_:1})]),n("p",null,[s[11]||(s[11]=a("作者：",-1)),e(i,{href:"https://opensource.com/users/seth"},{default:t(()=>[...s[7]||(s[7]=[a("Seth Kenlon",-1)])]),_:1}),s[12]||(s[12]=a(" 選題：",-1)),e(i,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[8]||(s[8]=[a("lujun9972",-1)])]),_:1}),s[13]||(s[13]=a(" 譯者：",-1)),e(i,{href:"https://github.com/geekpi"},{default:t(()=>[...s[9]||(s[9]=[a("geekpi",-1)])]),_:1}),s[14]||(s[14]=a(" 校對：",-1)),e(i,{href:"https://github.com/wxy"},{default:t(()=>[...s[10]||(s[10]=[a("wxy",-1)])]),_:1})]),n("p",null,[s[17]||(s[17]=a("本文由 ",-1)),e(i,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[15]||(s[15]=[a("LCTT",-1)])]),_:1}),s[18]||(s[18]=a(" 原創編譯，",-1)),e(i,{href:"https://linux.cn/"},{default:t(()=>[...s[16]||(s[16]=[a("Linux中國",-1)])]),_:1}),s[19]||(s[19]=a(" 榮譽推出",-1))])])}const T=p(d,[["render",u]]);export{C as __pageData,T as default};
